    add('198 210 234 362 950 951 1153 1225 1228 1232 1257 1260 1268 1272 1275 1338 1563 2359 2404 2453 2518 2528 2561 2570 2605 2632 4669','exclude_core','Section 230, FCC 인선, 플랫폼 또는 경쟁 규제에 관한 글이며 무역·관세 본 분석과 별도인 기업·규제 보조 범위다.')
    add('441 1367 1999 2638 2648 3168 3190 3492 3812 3813 3852 3853 3871 3892 3929 3946 3989 4184 4240 4260 4323 4325 4351 4397 4462 4495 4533 4657','exclude_core','보건·기업·국내 산업·재정·국제 항공 관련 글로 신규 관세·무역협정 발표가 확인되지 않는다. 다른 주제의 보조 분석에서는 별도 판정한다.')
    remaining=additional[~additional.raw_row.isin(set(assignments))].iloc[:80]
    inspected2='4682 4705 4713 4884 4911 4944 5049 5221 5314 5364 5389 5415 5467 5650 5709 5769 5959 5989 6290 6438 6453 6621 6656 6670 6683 6705 6707 6818 6881 6883 6899 6965 7005 7291 7386 7426 7448 7452 7470 7471 7474 7500 7693 7707 7755 8185 8257 8286 8411 8421 8427 8501 8506 8528 8549 8553 8555 8740 8843 8937 9010 9051 9165 9254 9381 9385 9388 9396 9454 9470 9567 9648 9649 9660 9995 10036 10127 10208 10218 10388'.split()
